#include <stdio.h>

/* 把 a 里 lo..mid 和 mid+1..hi 两摊各自排好的数，合起来成从小到大的一摊 */
void join(int a[], int lo, int mid, int hi) {
    int tmp[128];
    int i = lo;
    int j = mid + 1;
    int k = 0;

    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }
    while (i <= mid) {
        tmp[k++] = a[i++];
    }
    while (j <= hi) {
        tmp[k++] = a[j++];
    }

    for (int x = 0; x < k; x++) {
        a[lo + x] = tmp[x];
    }
}

/* 上一课那一招：把 a 里 lo..hi 这一段排成从小到大 */
void sort_half(int a[], int lo, int hi) {
    for (int i = lo; i < hi; i++) {
        for (int j = lo; j < hi - (i - lo); j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    int a[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1;
        }
    }

    int mid = (n - 1) / 2;
    sort_half(a, 0, mid);
    sort_half(a, mid + 1, n - 1);
    join(a, 0, mid, n - 1);

    printf("合起来：");
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    return 0;
}

explanationTemplate:
合起来这一招是「**两只手各指一个头，比一比再动手**」喵：

```text
while (i <= mid && j <= hi) {
    if (a[i] <= a[j]) tmp[k++] = a[i++];
    else tmp[k++] = a[j++];
}
while (i <= mid) tmp[k++] = a[i++];
while (j <= hi) tmp[k++] = a[j++];
for (int x = 0; x < k; x++) a[lo + x] = tmp[x];
```

三处值得多念两遍：

**① `i` 管左边那一摊、`j` 管右边那一摊，`k` 是「新排到第几位」。** 谁小谁先进 `tmp`，进去的那只手往后挪一格，另一只手不动 —— 这就是「谁小谁先走」。

**② 两个 `while` 一个都不能少。** 前面那一趟比对，是在「有一摊空了」的时候停下来的，可**停不等于搬完**：另一摊剩下的全是大的，得原样搬进去。只写一个的话，另一半的数据得靠运气才刚好对。

**③ 最后要整段搬回去。** `tmp` 只是暂存，`join` 干完活得让 `a` 的 `lo` 到 `hi` 这一段真的变成合好的样子 —— 一个 `for` 搬 `k` 只回去，别漏。

本喵给你留一句分头记：**谁小谁先走，走完的搬剩的，最后整段搬回家。**
